"""Algorithm B — Exact Type-Law and Entropy Profile of a Cyclotomic Subfield Tower.

For a prime conductor f and a degree d dividing f - 1, the splitting type of a prime p
in the degree-d subfield of Q(zeta_f) is the order of the class of p in a cyclic group
of order d.  Hence the type law is (phi(e)/d) for e | d, independent of f, and the whole
entropy profile can be produced in O(d log d) time with no reference to f whatsoever.
"""

from __future__ import annotations

from math import gcd, log2
from typing import Dict, List


def divisors(n: int) -> List[int]:
    small = [d for d in range(1, int(n**0.5) + 1) if n % d == 0]
    return sorted(set(small + [n // d for d in small]))


def totient(n: int) -> int:
    result, m, d = n, n, 2
    while d * d <= m:
        if m % d == 0:
            while m % d == 0:
                m //= d
            result -= result // d
        d += 1
    if m > 1:
        result -= result // m
    return result


def type_law(d: int) -> Dict[int, float]:
    """Law of the residue-degree type in the degree-d cyclic subfield: e |-> phi(e)/d."""
    return {e: totient(e) / d for e in divisors(d)}


def shannon(law: Dict[int, float]) -> float:
    total = -sum(p * log2(p) for p in law.values() if p > 0.0)
    return 0.0 if total == 0.0 else total


def renyi(law: Dict[int, float], order: float) -> float:
    ps = [p for p in law.values() if p > 0.0]
    if order == 1.0:
        return shannon(law)
    if order == float("inf"):
        return -log2(max(ps))
    return log2(sum(p**order for p in ps)) / (1.0 - order)


def saturation_constant(p: int) -> float:
    """C(p) = p log2 p /(p-1) - log2(p-1): the cap of the p-power tower."""
    return p * log2(p) / (p - 1) - (log2(p - 1) if p > 2 else 0.0)


def tower_profile(f_minus_one: int = 12) -> List[Dict[str, float]]:
    """Full entropy profile of every subfield degree dividing f - 1."""
    rows = []
    for d in divisors(f_minus_one):
        law = type_law(d)
        rows.append(
            {
                "degree": float(d),
                "H": shannon(law),
                "H2": renyi(law, 2.0),
                "Hinf": renyi(law, float("inf")),
            }
        )
    return rows


def check_crt_additivity(m: int, n: int) -> bool:
    """H(T_{mn}) = H(T_m) + H(T_n) whenever gcd(m, n) = 1."""
    if gcd(m, n) != 1:
        raise ValueError("degrees must be coprime")
    return abs(shannon(type_law(m * n)) - shannon(type_law(m)) - shannon(type_law(n))) < 1e-12


def check_prime_power_saturation(p: int, e: int) -> bool:
    """H(T_{p^e}) = C(p) (1 - p^-e)."""
    return abs(shannon(type_law(p**e)) - saturation_constant(p) * (1 - p ** (-e))) < 1e-12


if __name__ == "__main__":
    for row in tower_profile(12):
        print(
            f"degree {int(row['degree']):3d}   H = {row['H']:.10f}   "
            f"H_2 = {row['H2']:.10f}   H_inf = {row['Hinf']:.10f}"
        )
    print("CRT additivity 2 x 3 :", check_crt_additivity(2, 3))
    print("CRT additivity 4 x 3 :", check_crt_additivity(4, 3))
    print("saturation p=3, e=2  :", check_prime_power_saturation(3, 2))
    print("C(2), C(3) =", saturation_constant(2), saturation_constant(3))

"""Algorithm C — Semiprime Pairing Analyser with Rationality Certificate.

Given a prime degree q, the analyser folds the q x q joint table of factor classes into
the observable/hidden-pair joint law, returns the exact triple

    (H(T_q),  I_pair(q),  defect(q) = H - I_pair),

verifies it against the closed form  defect = ((q-1)^2/q^2) h(1/(q-1)),  confirms that the
which-factor mutual information is exactly zero, and emits a rationality certificate:
the integer identity that a rational defect would force, together with the odd prime that
refutes it.  Cost: O(q^2) for the table, O(1) for the closed form.
"""

from __future__ import annotations

from fractions import Fraction
from itertools import product
from math import gcd, log2
from typing import Dict, NamedTuple, Tuple


class PairingReport(NamedTuple):
    degree: int
    entropy: float
    pair_information: float
    defect: float
    closed_form: float
    which_factor_information: float
    decoder_success: float
    rational: bool
    certificate: str


def binary_entropy(x: float) -> float:
    if x <= 0.0 or x >= 1.0:
        return 0.0
    return -x * log2(x) - (1 - x) * log2(1 - x)


def mutual_information(joint: Dict[Tuple[object, object], float]) -> float:
    px: Dict[object, float] = {}
    py: Dict[object, float] = {}
    for (x, y), p in joint.items():
        px[x] = px.get(x, 0.0) + p
        py[y] = py.get(y, 0.0) + p
    return sum(p * log2(p / (px[x] * py[y])) for (x, y), p in joint.items() if p > 0.0)


def analyse(q: int) -> PairingReport:
    mass = 1.0 / (q * q)
    obs_pair: Dict[Tuple[object, object], float] = {}
    obs_label: Dict[Tuple[object, object], float] = {}
    mixed_mass = 0.0
    for a, b in product(range(q), repeat=2):
        ta = "split" if a == 0 else "inert"
        tb = "split" if b == 0 else "inert"
        pair = tuple(sorted((ta, tb)))
        observable = "split" if (a + b) % q == 0 else "inert"
        obs_pair[(observable, pair)] = obs_pair.get((observable, pair), 0.0) + mass
        if ta != tb:
            key = ((observable, pair), "first" if ta == "split" else "second")
            obs_label[key] = obs_label.get(key, 0.0) + mass
            mixed_mass += mass
    obs_label = {k: v / mixed_mass for k, v in obs_label.items()}

    h = binary_entropy(1.0 / q)
    i_pair = mutual_information(obs_pair)
    defect = h - i_pair
    closed = ((q - 1) ** 2 / q**2) * binary_entropy(1.0 / (q - 1))

    per_obs: Dict[object, Dict[object, float]] = {}
    for (obs, hid), p in obs_label.items():
        per_obs.setdefault(obs, {})[hid] = p
    success = sum(max(d.values()) for d in per_obs.values())

    return PairingReport(
        degree=q,
        entropy=h,
        pair_information=i_pair,
        defect=defect,
        closed_form=closed,
        which_factor_information=mutual_information(obs_label),
        decoder_success=success,
        rational=q in (2, 3),
        certificate=rationality_certificate(q),
    )


def rationality_certificate(q: int) -> str:
    """The integer identity a rational defect would force, and why it fails for q >= 5."""
    if q == 2:
        return "q = 2: defect = 0, rational (degenerate: h(1) = 0)."
    if q == 3:
        return "q = 3: defect = (4/9) h(1/2) = 4/9, rational."
    u, v = q - 1, q - 2
    odd = next((r for r in range(3, u + 1, 2) if u % r == 0 and is_prime(r)), None)
    if odd is not None:
        why = f"the odd prime {odd} divides {u} hence the left side, but gcd({u},{v}) = {gcd(u, v)} keeps it off the right"
    else:
        odd_v = next(r for r in range(3, v + 1, 2) if v % r == 0 and is_prime(r))
        why = f"{u} is a power of two while the odd prime {odd_v} divides {v}, hence the right side only"
    return (
        f"q = {q}: rationality would force {u}^({u}b) = 2^A * {v}^({v}b) for integers A, b >= 1; "
        f"{why}. Contradiction, so the defect is irrational."
    )


def is_prime(n: int) -> bool:
    return n > 1 and all(n % d for d in range(2, int(n**0.5) + 1))


if __name__ == "__main__":
    for q in (2, 3, 5, 7, 11, 13, 17):
        r = analyse(q)
        assert abs(r.defect - r.closed_form) < 1e-12
        assert abs(r.which_factor_information) < 1e-12
        assert abs(r.decoder_success - 0.5) < 1e-12
        print(
            f"q = {r.degree:3d}  H = {r.entropy:.8f}  I_pair = {r.pair_information:.8f}  "
            f"defect = {r.defect:.8f}  which-factor = {r.which_factor_information:.1e}"
        )
        print("      " + r.certificate)
    print("\ndegree 3 defect as an exact fraction:", Fraction(4, 9))
